import{_ as t,o as r,c as n,aj as o}from"./chunks/framework.C6uXqnaX.js";const h=JSON.parse('{"title":"Angular Roadmap","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md"}'),a={name:"roadmap.md"};function i(s,e,l,d,g,p){return r(),n("div",null,e[0]||(e[0]=[o('<h1 id="angular-roadmap" tabindex="-1">Angular Roadmap <a class="header-anchor" href="#angular-roadmap" aria-label="Permalink to &quot;Angular Roadmap&quot;">​</a></h1><p>Learn how the Angular team is building momentum on the web.</p><p>As an open source project, Angular’s daily commits, PRs and momentum is all trackable on GitHub. To increase transparency into how this daily work connects to the framework’s future, our roadmap brings together the team’s current and future planned vision.</p><p>The following projects are not associated with a particular Angular version. We will release them on completion, and they will be part of a specific version based on our release schedule, following semantic versioning. For example, we release features in the next minor after completion or the next major if they include breaking changes.</p><p>Currently, Angular has three goals for the framework:</p><ol><li>Improve the <a href="/ai">AI experience for developers</a></li><li>Improve the <a href="#improving-the-angular-developer-experience">Angular developer experience</a></li><li>Improve the framework’s performance</li></ol><p>Continue reading to learn how we plan to deliver these objectives with specific project work.</p><h2 id="explore-modern-angular" tabindex="-1">Explore modern Angular <a class="header-anchor" href="#explore-modern-angular" aria-label="Permalink to &quot;Explore modern Angular&quot;">​</a></h2><p>Start developing with the latest Angular features from our roadmap. This list represents the current status of new features from our roadmap:</p><h3 id="available-to-experiment-with" tabindex="-1">Available to experiment with <a class="header-anchor" href="#available-to-experiment-with" aria-label="Permalink to &quot;Available to experiment with&quot;">​</a></h3><ul><li><a href="/ai/webmcp">Web MCP</a></li></ul><h3 id="production-ready" tabindex="-1">Production ready <a class="header-anchor" href="#production-ready" aria-label="Permalink to &quot;Production ready&quot;">​</a></h3><ul><li><a href="/guide/forms/signals/overview">Signal Forms</a></li><li><a href="/guide/signals/resource">Resource API</a></li><li><a href="https://angular.dev/api/common/http/httpResource" target="_blank" rel="noreferrer">httpResource</a></li><li><a href="/guide/zoneless">Zoneless change detection</a></li><li><a href="/guide/signals/linked-signal">Linked Signal API</a></li><li><a href="/guide/incremental-hydration">Incremental hydration</a></li><li><a href="https://angular.dev/api/core/effect" target="_blank" rel="noreferrer">Effect API</a></li><li><a href="https://angular.dev/api/platform-browser/withEventReplay" target="_blank" rel="noreferrer">Event replay with SSR</a></li><li><a href="/guide/ssr">Route-level render mode</a></li></ul><h2 id="improving-the-ai-experience-for-angular-developers" tabindex="-1">Improving the AI experience for Angular Developers <a class="header-anchor" href="#improving-the-ai-experience-for-angular-developers" aria-label="Permalink to &quot;Improving the AI experience for Angular Developers&quot;">​</a></h2><h3 id="bringing-the-best-of-ai-to-angular" tabindex="-1">Bringing the best of AI to Angular <a class="header-anchor" href="#bringing-the-best-of-ai-to-angular" aria-label="Permalink to &quot;Bringing the best of AI to Angular&quot;">​</a></h3><ul><li><strong>AI Powered Angular</strong>: AI continues to shape the development landscape. It has changed how we develop apps and the types of user experiences that are possible. We plan to best support the developer community in AI-assisted coding and integrating AI in their applications.</li><li><strong>AI Development</strong>: The team will continue to develop meaningful integrations with tools like Google AI Studio, Gemini CLI and other agentic tooling such as Agentic IDEs like Antigravity. We plan to launch solutions that stay in line with the rapidly evolving industry. Some examples include agent skills, new MCP features and AI SDKs.</li><li><strong>Code Generation</strong>: <a href="https://blog.angular.dev/beyond-the-horizon-how-angular-is-embracing-ai-for-next-gen-apps-7a7ed706e1a3" target="_blank" rel="noreferrer">Based on our research</a>, code generation for Angular is already high quality with modern LLMs. We will continue our investments in improving code generation for Angular. This means we will regularly evaluate code generation quality using current models and work to improve it through system instructions, documentation, and tactical framework changes.</li><li><strong>AI Powered Experiences</strong>: There is a new frontier for Angular developers to explore with new concepts such as Dynamic UI generation. We started with building Angular support for A2UI and are actively searching out more opportunities to support modern application experiences.</li></ul><h2 id="improving-the-angular-developer-experience" tabindex="-1">Improving the Angular developer experience <a class="header-anchor" href="#improving-the-angular-developer-experience" aria-label="Permalink to &quot;Improving the Angular developer experience&quot;">​</a></h2><h3 id="developer-velocity" tabindex="-1">Developer velocity <a class="header-anchor" href="#developer-velocity" aria-label="Permalink to &quot;Developer velocity&quot;">​</a></h3><ul><li><strong>Compiler</strong>: Microsoft has spent the last year porting the TypeScript compiler to Go, with the promise of a 5 - 10x speedup for typical TypeScript compilations. Angular has perhaps one of the deepest integrations with the TypeScript compiler, which will require bigger architectural changes to support new tsgo-based workflows for both the compiler and language service. We&#39;re in the process of prototyping and exploring what this support would look like, and will deliver an Angular compiler that is compatible with tsgo and brings the performance benefits of Microsoft&#39;s native port to the Angular ecosystem.</li><li><strong>Enhanced Ecosystem compatibility</strong>: Developers are mixing AI generated code with manually generated code, and want to make use of popular libraries and integrate new experiences quickly. Angular wants to integrate well into that ecosystem - developers should be able to use the tools they love and mix and match frameworks according to their requirements. As part of this project, we&#39;ll explore the requirement space of cross framework interop and our build tooling to improve our compatibility.</li><li><strong>Components</strong>: In Angular v21, we launched Angular Aria in developer preview, providing eight patterns for accessible, headless components. In Angular v22, we promoted Angular Aria to stable, and we plan to introduce new patterns where needed. We want to provide developers with a solid foundation for developing their own components using Angular Aria - we provide the interactions and you bring the style that matches your design systems. Developers will have the choice of developing custom components with Angular Aria, use interaction patterns from the CDK, or use ready-made styled Material Components. For accessibility, we are continuously evaluating the components and patterns against accessibility standards such as WCAG and are working to fix any issues that arise from this process.</li></ul><h3 id="improve-tooling" tabindex="-1">Improve tooling <a class="header-anchor" href="#improve-tooling" aria-label="Permalink to &quot;Improve tooling&quot;">​</a></h3><ul><li><strong>Modernize unit testing tooling with ng test</strong>: Following the stable release of Vitest in Angular v21, it is now our primary test runner. We are now focused on promoting our experimental Karma to Vitest migration tool to stable as well as investigating new features to further refine and improve the developer testing workflow.</li></ul><h2 id="completed-projects" tabindex="-1">Completed projects <a class="header-anchor" href="#completed-projects" aria-label="Permalink to &quot;Completed projects&quot;">​</a></h2><ul><li><a href="/guide/forms/signals/overview"><strong>Signal Forms</strong></a>: Signal Forms are now stable. This new approach allows developers to manage form state using signals, providing an ergonomic forms creation experience. We promoted Signal Forms to stable and enhanced interoperability with reactive forms - enabling teams to progressively migrate large forms at their own pace.</li><li><a href="/guide/signals"><strong>Reactivity</strong></a>: We introduced new signal APIs, <code>resource()</code> and <code>httpResource()</code>, for flexible asynchronous data handling. We promoted these APIs to developer stable.</li><li><a href="https://angular.dev/api/core/ChangeDetectionStrategy" target="_blank" rel="noreferrer"><strong>Change Detection</strong></a>: With Zoneless being stable and default, we set the default change detection strategy to <code>OnPush</code>, to follow current best practices. We also renamed <code>ChangeDetectionStrategy.Default</code> to <code>ChangeDetectionStrategy.Eager</code>. <a href="https://github.com/angular/angular/discussions/66779" target="_blank" rel="noreferrer">See the RFC discussion for details</a>.</li><li><strong>Signal debugging in Angular DevTools</strong>: We&#39;ve added better tooling for debugging Signals using Angular DevTools. This change includes a new UI for inspecting and debugging signals.</li><li><a href="https://github.com/angular/angular/issues/39367#issuecomment-1439537306" target="_blank" rel="noreferrer"><strong>Improve HMR (Hot Module Reload)</strong></a>: We&#39;re working towards faster edit/refresh cycle by enabling hot module replacement. In Angular v19 we shipped initial support for CSS and template HMR and in v20 we graduated template HMR to stable. We&#39;ll continue collecting feedback to make sure we&#39;re addressing developers&#39; needs before we mark this project as complete.</li><li><strong>Zoneless Angular</strong>: In v18 we shipped experimental zoneless support in Angular. It enables developers to use the framework without including zone.js in their bundle, which improves performance, debugging experience, and interoperability. As part of the initial release we also introduced zoneless support to the Angular CDK and Angular Material. In v19 we introduced zoneless support in server-side rendering, addressed some edge cases, and created a schematic to scaffold zoneless projects. We transitioned <a href="https://fonts.google.com/" target="_blank">Google Fonts</a> to zoneless which improved performance, developer experience, and allowed us to identify gaps that we need to address before moving this feature to developer preview. As of Angular v20.2, Zoneless Angular is now stable and includes improvements in error handling and server-side rendering.</li><li><strong>Server route configuration</strong>: We&#39;re working towards enabling a more ergonomic route configuration on the server. We want to make it trivial to declare which routes should be server-side rendered, prerendered or client-side rendered. In Angular v19 we shipped developer preview of route-level render mode which allows you to granularly configure which routes you want Angular to prerender, server-side render or client-side render. In Angular v20 we graduated it to stable.</li><li><strong>Enable incremental hydration</strong>: In v17 we graduated hydration from developer preview and we&#39;ve been consistently observing 40-50% improvements in LCP. Since then we started prototyping incremental hydration and shared a demo on stage at ng-conf. In v19 we shipped the incremental hydration in developer preview mode, powered by <code>@defer</code> blocks. In Angular v20 we graduated it to stable!</li><li><a href="https://github.com/angular/angular/discussions/49685" target="_blank" rel="noreferrer"><strong>Deliver Angular Signals</strong></a>: This project rethinks the Angular reactivity model by introducing Signals as a reactivity primitive. The initial planning resulted in hundreds of discussions, conversations with developers, feedback sessions, user experience studies, and a series of RFCs, which received over 1,000 comments. In Angular v20 we graduated all the fundamental reactivity primitives to stable including signal, effect, linkedSignal, signal-based queries, and inputs.</li><li><a href="https://github.com/angular/components/issues/13372" target="_blank" rel="noreferrer"><strong>Support two-dimensional drag-and-drop</strong></a>: As part of this project, we implemented mixed orientation support for the Angular CDK drag and drop. This is one of the repository&#39;s most highly requested features.</li><li><a href="https://angular.dev/api/platform-browser/withEventReplay" target="_blank" rel="noreferrer"><strong>Event replay with SSR and prerendering</strong></a>: In v18 we introduced an event replay functionality when using server-side rendering or prerendering. For this feature we depend on the event dispatch primitive (previously known as jsaction) that is running on Google.com. In Angular v19 we graduated event replay to stable and enabled it by default for all new projects.</li><li><strong>Integrate Angular Language Service with Schematics</strong>: To make it easier for developers to use modern Angular APIs, we enabled integration between the Angular language service and schematics which allows you to refactor your app with a single click.</li><li><strong>Streamline standalone imports with Language Service</strong>: As part of this initiative, the language service automatically imports components and pipes in standalone and NgModule-based apps. Additionally, we&#39;ve added a template diagnostic to highlight unused imports in standalone components, which should help make application bundles smaller.</li><li><strong>Local template variables</strong>: We&#39;ve released the support for local template variables in Angular, see <a href="https://angular.dev/api/core/@let" target="_blank" rel="noreferrer"><code>@let</code></a> for additional information.</li><li><a href="https://material.angular.dev/guide/theming" target="_blank" rel="noreferrer"><strong>Expand the customizability of Angular Material</strong></a>: To provide better customization of our Angular Material components and enable Material 3 capabilities, we&#39;ll be collaborating with Google&#39;s Material Design team on defining token-based theming APIs. In v17.2 we shared experimental support for Angular Material 3 and in v18 we graduated it to stable.</li><li><a href="/guide/templates/defer"><strong>Introduce deferred loading</strong></a>: In v17 we shipped deferrable views in developer preview, which provide an ergonomic API for deferred code loading. In v18 we enabled deferrable views for library developers and graduated the API to stable.</li><li><strong>iframe support in Angular DevTools</strong>: We enabled debugging and profiling of Angular apps embedded within an iframe on the page.</li><li><a href="/tools/cli/build-system-migration"><strong>Automation for transition of existing hybrid rendering projects to esbuild and vite</strong></a>: In v17 we shipped a vite and esbuild-based application builder and enabled it for new projects by default. It improves build time for projects using hybrid rendering with up to 87%. As part of v18 we shipped schematics and a guide that migrate existing projects using hybrid rendering to the new build pipeline.</li><li><a href="https://goo.gle/angular-dot-dev" target="_blank" rel="noreferrer"><strong>Make Angular.dev the official home for Angular developers</strong></a>: Angular.dev is the new site, domain and home for Angular development. The new site contains updated documentation, tutorials and guidance that will help developers build with Angular’s latest features.</li><li><a href="/guide/templates/control-flow"><strong>Introduce built-in control flow</strong></a>: In v17 we shipped a developer preview version of a new control flow. It brings significant performance improvements and better ergonomics for template authoring. We also provided a migration of existing <code>*ngIf</code>, <code>*ngFor</code>, and <code>*ngSwitch</code> which you can run to move your project to the new implementation. As of v18 the built-in control flow is now stable.</li><li><strong>Modernize getting started tutorial</strong>: Over the past two quarters, we developed a new <a href="https://www.youtube.com/watch?v=xAT0lHYhHMY&amp;list=PL1w1q3fL4pmj9k1FrJ3Pe91EPub2_h4jF" target="_blank" rel="noreferrer">video</a> and <a href="/tutorials/learn-angular">textual</a> tutorial based on standalone components.</li><li><a href="/guide/hydration"><strong>Investigate modern bundlers</strong></a>: In Angular v16, we released a developer preview of an esbuild-based builder with support for <code>ng build</code> and <code>ng serve</code>. The <code>ng serve</code> development server uses Vite and a multi-file compilation by esbuild and the Angular compiler. In v17 we graduated the build tooling from developer preview and enabled it by default for new projects.</li><li><a href="/tools/devtools"><strong>Introduce dependency injection debugging APIs</strong></a>: To improve the debugging utilities of Angular and Angular DevTools, we&#39;ll work on APIs that provide access to the dependency injection runtime. As part of the project, we&#39;ll expose debugging methods that allow us to explore the injector hierarchy and the dependencies across their associated providers. As of v17, we shipped a feature that enables us to plug into the dependency injection life-cycle. We also launched a visualization of the injector tree and inspection of the providers declared inside each individual node,</li><li><a href="/essentials/components"><strong>Improve documentation and schematics for standalone components</strong></a>: We released a developer preview of the <code>ng new --standalone</code> schematics collection, allowing you to create apps free of NgModules. In v17 we switched the new application authoring format to standalone APIs and changed the documentation to reflect the recommendation. Additionally, we shipped schematics which support updating existing applications to standalone components, directives, and pipes. Even though NgModules will stick around for foreseeable future, we recommend you to explore the benefits of the new APIs to improve developer experience and benefit from the new features we build for them.</li><li><strong>Explore hydration and server-side rendering improvements</strong>: In v16, we released a developer preview of non-destructive full hydration, see the <a href="/guide/hydration">hydration guide</a> and the <a href="https://blog.angular.dev/whats-next-for-server-side-rendering-in-angular-2a6f27662b67" target="_blank" rel="noreferrer">blog post</a> for additional information. We&#39;re already seeing significant improvements to Core Web Vitals, including <a href="https://web.dev/lcp" target="_blank" rel="noreferrer">LCP</a> and <a href="https://web.dev/cls" target="_blank" rel="noreferrer">CLS</a>. In lab tests, we consistently observed 45% better LCP of a real-world app. In v17 we launched hydration outside developer preview and did a series of improvements in the server-side rendering story, including: route discovery at runtime for SSG, up to 87% faster build times for hybrid rendered applications, prompt that enables hybrid rendering for new projects.</li><li><a href="/guide/hydration"><strong>Non-destructive full app hydration</strong></a>: In v16, we released a developer preview of non-destructive full hydration, which allows Angular to reuse existing DOM nodes on a server-side rendered page, instead of re-creating an app from scratch. See additional information in the hydration guide.</li><li><a href="/guide/image-optimization"><strong>Improvements in the image directive</strong></a>: We released the Angular image directive as stable in v15. We introduced a new fill mode feature that enables images to fit within their parent container rather than having explicit dimensions. Over the past two months, the Chrome Aurora team backported the directive to v12 and newer.</li><li><a href="https://angular.io" target="_blank" rel="noreferrer"><strong>Documentation refactoring</strong></a>: Ensure all existing documentation fits into a consistent set of content types. Update excessive use of tutorial-style documentation into independent topics. We want to ensure the content outside the main tutorials is self-sufficient without being tightly coupled to a series of guides. In Q2 2022, we refactored the template content and dependency injection. In Q1 2023, we improved the HTTP guides, and with this, we&#39;re putting the documentation refactoring project on hold.</li><li><a href="/guide/image-optimization"><strong>Improve image performance</strong></a>: The Aurora and the Angular teams are working on the implementation of an image directive that aims to improve Core Web Vitals. We shipped a stable version of the image directive in v15.</li><li><a href="https://blog.angular.dev/modern-css-in-angular-layouts-4a259dca9127" target="_blank" rel="noreferrer"><strong>Modern CSS</strong></a>: The Web ecosystem evolves constantly and we want to reflect the latest modern standards in Angular. In this project we aim to provide guidelines on using modern CSS features in Angular to ensure developers follow best practices for layout, styling, etc. We shared official guidelines for layout and as part of the initiative stopped publishing flex layout.</li><li><a href="/guide/directives/directive-composition-api"><strong>Support adding directives to host elements</strong></a>: A long-standing feature request is to add the ability to add directives to host elements. The feature lets developers augment their own components with additional behaviors without using inheritance. In v15 we shipped our directive composition API, which enables enhancing host elements with directives.</li><li><a href="https://developer.chrome.com/blog/devtools-better-angular-debugging/" target="_blank" rel="noreferrer"><strong>Better stack traces</strong></a>: The Angular and the Chrome DevTools are working together to enable more readable stack traces for error messages. In v15 we released improved relevant and linked stack traces. As a lower priority initiative, we&#39;ll be exploring how to make the stack traces friendlier by providing more accurate call frame names for templates.</li><li><a href="https://material.angular.dev/guide/mdc-migration" target="_blank" rel="noreferrer"><strong>Enhanced Angular Material components by integrating MDC Web</strong></a>: MDC Web is a library created by the Google Material Design team that provides reusable primitives for building Material Design components. The Angular team is incorporating these primitives into Angular Material. Using MDC Web aligns Angular Material more closely with the Material Design specification, expands accessibility, improves component quality, and improves the velocity of our team.</li><li><a href="https://blog.angular.dev/angular-v15-is-now-available-df7be7f2f4c8" target="_blank" rel="noreferrer"><strong>Implement APIs for optional NgModules</strong></a>: In the process of making Angular simpler, we are working on introducing APIs that allow developers to initialize apps, instantiate components, and use the router without NgModules. Angular v14 introduces developer preview of the APIs for standalone components, directives, and pipes. In the next few quarters we&#39;ll collect feedback from developers and finalize the project making the APIs stable. As the next step we will work on improving use cases such as TestBed, Angular elements, etc.</li><li><a href="/guide/templates/binding"><strong>Allow binding to protected fields in templates</strong></a>: To improve the encapsulation of Angular components we enabled binding to protected members of the component instance. This way you&#39;ll no longer have to expose a field or a method as public to use it inside your templates.</li><li><a href="https://angular.io/guide/change-detection" target="_blank" rel="noreferrer"><strong>Publish guides on advanced concepts</strong></a>: Develop and publish an in-depth guide on change detection. Develop content for performance profiling of Angular apps. Cover how change detection interacts with Zone.js and explain when it gets triggered, how to profile its duration, as well as common practices for performance optimization.</li><li><a href="/guide/forms/typed-forms"><strong>Rollout strict typings for @angular/forms</strong></a>: In Q4 2021 we designed a solution for introducing strict typings for forms and in Q1 2022 we concluded the corresponding request for comments. Currently, we are implementing a rollout strategy with an automated migration step that will enable the improvements for existing projects. We are first testing the solution with more than 2,500 projects at Google to ensure a smooth migration path for the external community.</li><li><a href="https://blog.angular.dev/angular-v15-is-now-available-df7be7f2f4c8" target="_blank" rel="noreferrer"><strong>Remove legacy View Engine</strong></a>: After the transition of all our internal tooling to Ivy is completed, we will remove the legacy View Engine for reduced Angular conceptual overhead, smaller package size, lower maintenance cost, and lower codebase complexity.</li><li><a href="https://blog.angular.dev/angular-v15-is-now-available-df7be7f2f4c8" target="_blank" rel="noreferrer"><strong>Simplified Angular mental model with optional NgModules</strong></a>: To simplify the Angular mental model and learning journey, we will be working on making NgModules optional. This work lets developers develop standalone components and implement an alternative API for declaring the compilation scope of the component. We kicked this project off with high-level design discussions that we captured in an RFC.</li><li><a href="/guide/forms/typed-forms"><strong>Design strict typing for @angular/forms</strong></a>: We will work on finding a way to implement stricter type checking for reactive forms with minimal backward incompatible implications. This way, we let developers catch more issues during development time, enable better text editor and IDE support, and improve the type checking for reactive forms.</li><li><a href="/tools/devtools"><strong>Improve integration of Angular DevTools with framework</strong></a>: To improve the integration of Angular DevTools with the framework, we are working on moving the codebase to the angular/angular monorepository. This includes transitioning Angular DevTools to Bazel and integrating it into the existing processes and CI pipeline.</li><li><a href="/extended-diagnostics"><strong>Launch advanced compiler diagnostics</strong></a>: Extend the diagnostics of the Angular compiler outside type checking. Introduce other correctness and conformance checks to further guarantee correctness and best practices.</li><li><a href="/guide/testing"><strong>Update our e2e testing strategy</strong></a>: To ensure we provide a future-proof e2e testing strategy, we want to evaluate the state of Protractor, community innovations, e2e best practices, and explore novel opportunities. As first steps of the effort, we shared an RFC and worked with partners to ensure smooth integration between the Angular CLI and state-of-the-art tooling for e2e testing. As the next step, we need to finalize the recommendations and compile a list of resources for the transition.</li><li><a href="/tools/libraries"><strong>Angular libraries use Ivy</strong></a>: Earlier in 2020, we shared an RFC for Ivy library distribution. After invaluable feedback from the community, we developed a design of the project. We are now investing in the development of Ivy library distribution, including an update of the library package format to use Ivy compilation, unblock the deprecation of the View Engine library format, and ngcc.</li><li><a href="/guide/testing"><strong>Improve test times and debugging with automatic test environment tear down</strong></a>: To improve test time and create better isolation across tests, we want to change TestBed to automatically clean up and tear down the test environment after each test run.</li><li><a href="https://github.com/angular/angular/issues/41840" target="_blank" rel="noreferrer"><strong>Deprecate and remove IE11 support</strong></a>: Internet Explorer 11 (IE11) has been preventing Angular from taking advantage of some of the modern features of the Web platform. As part of this project we are going to deprecate and remove IE11 support to open the path for modern features that evergreen browsers provide. We ran an RFC to collect feedback from the community and decide on next steps to move forward.</li><li><a href="https://www.typescriptlang.org/docs/handbook/tsconfig-json.html" target="_blank" rel="noreferrer"><strong>Leverage ES2017+ as the default output language</strong></a>: Supporting modern browsers lets us take advantage of the more compact, expressive, and performant new syntax of JavaScript. As part of this project we will investigate what the blockers are to moving forward with this effort, and take the steps to enable it.</li><li><a href="/tools/devtools"><strong>Accelerated debugging and performance profiling with Angular DevTools</strong></a>: We are working on development tooling for Angular that provides utilities for debugging and performance profiling. This project aims to help developers understand the component structure and the change detection in an Angular app.</li><li><a href="/reference/releases"><strong>Streamline releases with consolidated Angular versioning &amp; branching</strong></a>: We want to consolidate release management tooling between the multiple GitHub repositories for Angular (angular/angular, angular/angular-cli, and angular/components). This effort lets us reuse infrastructure, unify and simplify processes, and improve the reliability of our release process.</li><li><a href="https://github.com/angular/angular" target="_blank" rel="noreferrer"><strong>Higher developer consistency with commit message standardization</strong></a>: We want to unify commit message requirements and conformance across Angular repositories (angular/angular, angular/components, and angular/angular-cli) to bring consistency to our development process and reuse infrastructure tooling.</li><li><a href="/tools/language-service"><strong>Transition the Angular language service to Ivy</strong></a>: The goal of this project is to improve the experience and remove legacy dependency by transitioning the language service to Ivy. Today the language service still uses the View Engine compiler and type checking, even for Ivy apps. We want to use the Ivy template parser and improved type checking for the Angular Language service to match app behavior. This migration is also a step towards unblocking the removal of View Engine, which will simplify Angular, reduce the npm package size, and improve the maintainability of the framework.</li><li><a href="/best-practices/security"><strong>Increased security with native Trusted Types in Angular</strong></a>: In collaboration with the Google security team, we are adding support for the new Trusted Types API. This web platform API helps developers build more secure web apps.</li><li><a href="/tools/cli/build"><strong>Optimized build speed and bundle sizes with Angular CLI webpack 5</strong></a>: As part of the v11 release, we introduced an opt-in preview of webpack 5 in the Angular CLI. To ensure stability, we will continue iterating on the implementation to enable build speed and bundle size improvements.</li><li><a href="/guide/ssr"><strong>Faster apps by inlining critical styles in Universal apps</strong></a>: Loading external stylesheets is a blocking operation, which means that the browser cannot start rendering your app until it loads all the referenced CSS. Having render-blocking resources in the header of a page can significantly impact its load performance, for example, its first contentful paint. To make apps faster, we have been collaborating with the Google Chrome team on inlining critical CSS and loading the rest of the styles asynchronously.</li><li><a href="/errors"><strong>Improve debugging with better Angular error messages</strong></a>: Error messages often bring limited actionable information to help developers resolve them. We have been working on making error messages more discoverable by adding associated codes, developing guides, and other materials to ensure a smoother debugging experience.</li><li><a href="/tutorials"><strong>Improved developer onboarding with refreshed introductory documentation</strong></a>: We will redefine the user learning journeys and refresh the introductory documentation. We will clearly state the benefits of Angular, how to explore its capabilities and provide guidance so developers can become proficient with the framework in as little time as possible.</li><li><a href="https://material.angular.dev/guide/using-component-harnesses" target="_blank" rel="noreferrer"><strong>Expand component harnesses best practices</strong></a>: Angular CDK introduced the concept of component test harnesses to Angular in version 9. Test harnesses let component authors create supported APIs for testing component interactions. We are continuing to improve this harness infrastructure and clarifying the best practices around using harnesses. We are also working to drive more harness adoption inside of Google.</li><li><a href="https://angular.io/docs" target="_blank" rel="noreferrer"><strong>Author a guide for content projection</strong></a>: Content projection is a core Angular concept that does not have the presence it deserves in the documentation. As part of this project we want to identify the core use cases and concepts for content projection and document them.</li><li><a href="/tools/cli"><strong>Migrate to ESLint</strong></a>: With the deprecation of TSLint we will be moving to ESLint. As part of the process, we will work on ensuring backward compatibility with our current recommended TSLint configuration, implement a migration strategy for existing Angular apps and introduce new tooling to the Angular CLI toolchain.</li><li><a href="https://github.com/angular/angular/issues" target="_blank" rel="noreferrer"><strong>Operation Bye Bye Backlog (also known as Operation Byelog)</strong></a>: We are actively investing up to 50% of our engineering capacity on triaging issues and PRs until we have a clear understanding of broader community needs. After that, we will commit up to 20% of our engineering capacity to keep up with new submissions promptly.</li></ul>',23)]))}const u=t(a,[["render",i]]);export{h as __pageData,u as default};
